// 程序坞放大的数学（macOS 程序坞的手感）：拓展坞（shell.js initDock）和开源广场里的“程序坞放大”试玩共用。
// 坐标只用一个轴：竖着的坞传 top / h，横着的传 left / w，算法一样。纯函数，不碰 DOM。

/** 每一项想要放大到多少：离指针越近越大，range 以外不放大（余弦衰减，中间最大 1 + max） */
export function dockTargets(items, pointer, { max = 0.5, range = 140 } = {}) {
  return items.map((it) => {
    if (it.grow === false) return 1;
    const d = Math.abs(pointer - (it.start + it.size / 2));
    return d >= range ? 1 : 1 + max * (1 + Math.cos(Math.PI * d / range)) / 2;
  });
}

/**
 * 按当前的放大倍数排开：各项依次往后让位，再整体挪一下，让指针下面那一点不动（点得准）。
 * 返回每一项的位移（中心点挪了多少）、总共多出来的长度、底板该往前伸出的长度。
 */
export function dockLayout(items, scales, pointer) {
  const extra = items.map((it, i) => (scales[i] - 1) * it.size);
  const total = extra.reduce((a, b) => a + b, 0);
  let anchor = total / 2;
  if (pointer != null) {
    anchor = 0;
    for (let i = 0, before = 0; i < items.length; i++) {
      const it = items[i];
      if (pointer >= it.start + it.size) { before += extra[i]; anchor = before; continue; }
      anchor = before + extra[i] * Math.min(1, Math.max(0, (pointer - it.start) / it.size));
      break;
    }
  }
  let before = 0;
  const shifts = items.map((it, i) => {
    const shift = before + extra[i] / 2 - anchor;
    before += extra[i];
    return shift;
  });
  return { shifts, total, anchor };
}

